import test from 'node:test';
import assert from 'node:assert/strict';
import {createCareState,advanceNeeds,reserveJob,collect,deliver,cancelJob} from './ranch-life-state.mjs';
import {pathNetwork} from './ranch-routes.mjs';
test('animals consume only when they reach the resource',()=>{const s=createCareState([{id:'p',species:'horse',count:1}]);advanceNeeds(s,1);assert.equal(s.used.water,0);s.pens[0].animals[0].atWater=true;advanceNeeds(s,1);assert.ok(s.used.water>0);});
test('care jobs reserve independently and conserve carried resources',()=>{const s=createCareState([{id:'p',species:'goat',count:3}]);const a=reserveJob(s,'a'),b=reserveJob(s,'b');assert.notEqual(a.resource,b.resource);assert.equal(reserveJob(s,'c'),null);collect(s,a);collect(s,b);deliver(s,a);cancelJob(s,b);for(const r of ['water','feed'])assert.equal(s.stock[r]+s.pens[0][r],s.initial[r]);assert.equal(s.jobs,1);});
test('long-running baseline replenishes, bounded consumption conserves resources',()=>{const s=createCareState([{id:'p',species:'chicken',count:5}]);for(const a of s.pens[0].animals){a.atWater=true;a.atFeed=true;}for(let i=0;i<10000;i++){advanceNeeds(s,.5);const job=reserveJob(s,'worker');if(job){collect(s,job);deliver(s,job);}}for(const r of ['feed','water']){assert.ok(s.stock[r]>0);assert.ok(Math.abs(s.stock[r]+s.pens[0][r]+s.used[r]-s.initial[r]-s.replenished[r])<1e-7);}assert.ok(s.pens[0].animals.every(a=>a.hunger<.5&&a.thirst<.5));});
test('route graph connects T junctions but rejects disconnected paths',()=>{const graph=pathNetwork([{center:{x:0,z:0},paths:[{points:[{x:0,z:0},{x:10,z:0}]},{points:[{x:5,z:0},{x:5,z:5}]},{points:[{x:20,z:20},{x:25,z:20}]}]}]);assert.deepEqual(graph.route({x:0,z:0},{x:5,z:5}),[{x:0,z:0},{x:5,z:0},{x:5,z:5}]);assert.equal(graph.route({x:0,z:0},{x:20,z:20}),null);});
